[ExtensionOf(formStr(DirPartyLookup))]
final class AVADirPartyLookupFrm_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>FormRun</returns>
public FormRun AVAgetcallerForm()
{
    return callerForm;
}

/// <summary>
/// designed from AVA
/// </summary>
public void addRanges()
{
    next addRanges();
    if (    callerForm.name() == formStr(AVAKBVCreateBuildingProjectTable) 
        ||  callerForm.name() == formStr(AVAKBVCreateRequestTable)
        ||  callerForm.name() == formStr(AVAKBVBuildingProjectTable)
        ||  callerForm.name() == formStr(AVAKBVRequestTable)
        ||  callerForm.name() == formStr(AVAKBVInquirerOfTheRequest)
        ||  callerForm.name() == formStr(CustTable) 
        ||  callerForm.name() == formStr(smmBusRelTable) 
        ||  callerForm.name() == formStr(DirPartyTable)                     )
    {
        Query                       queryDirPartyTable      = DirPartyTable_DirOrganizationBase_ds.query();
        QueryBuildDataSource        dirOrganizationBase_ds  =   queryDirPartyTable.dataSourceTable(tableNum(DirPartyTable));
        QueryBuildRange             blockedRange            = SysQuery::findOrCreateRange(dirOrganizationBase_ds,fieldNum(DirOrganizationBase,AVABVBlocked));
        blockedRange.value(enum2Str(NoYes::No));
        Query                       dirPartyTableQ          = DirPartyTable_ds.query();
        QueryBuildDataSource        dirPartyTable_ds        = dirPartyTableQ.dataSourceTable(tableNum(DirPartyTable));

        str                         filterTableStr          = tableStr(DirPartyTable);
        str                         filterFieldStr          = fieldStr(DirPartyTable, Name);

        FilterValue filterValue;
        Name        filterStr;

        Object test = this.args().caller();

        if (this.args().caller() is FormReferenceGroupControl)
        {
            filterValue = referenceControl.filterValue(AbsoluteFieldBinding::construct(filterFieldStr, filterTableStr));
            filterStr = filterValue.value();
        }

        if (this.args().caller() is FormRun)
        {
            if (this.args().callerFormControl() is FormReferenceGroupControl)
            {
                filterValue = referenceControl.filterValue(AbsoluteFieldBinding::construct(filterFieldStr, filterTableStr));
                filterStr = filterValue.value();
            }
        }

        if(this.args().caller() is FormStringControl)
        {
            FormStringControl formStringControl = this.args().caller() as FormStringControl;
            // User input values should be taken literally to maintain compatibility with the SysTableLookup functionality.
            filterStr = SysQueryRangeUtil::literalFilterValue(formStringControl.text());
        }

        if (filterStr != '')
        {
            QueryBuildRange     nameRange;
            nameRange = SysQuery::findOrCreateRange(dirPartyTable_ds,fieldNum(DirPartyTable,Name));
            nameRange.value(strFmt('((((%1.%2) like \"*%3*\") || ((%1.%4) like \"*%3*\")))',dirPartyTable_ds.name(),fieldStr(DirPartyTable,Name),filterStr,fieldStr(DirPartyTable,NameAlias)));
        }

    }
}
